'use strict';
const C=MissionCore,$=id=>document.getElementById(id),KEY='mission-control:state:v4';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let today=C.dateKey(new Date()),week=C.weekKey(today),current=(new Date().getDay()+6)%7,view='today',historyWeek=week,data,storageOK=true;
try{const raw=localStorage.getItem(KEY);data=raw?JSON.parse(raw):C.migrate(C.empty(),localStorage);if(data.version!==4||!data.weeks||!data.longGoals||!data.months)throw Error('Unrecognized saved data');}catch(e){data=C.empty();storageOK=false;}
C.upgrade(data);
AcademicTracker.ensure(data);GoalPlanner.ensure(data);
function appNow(){return C.zonedNow(new Date(),data.timezone)}
today=C.dateKey(appNow());week=C.weekKey(today);current=(appNow().getDay()+6)%7;
C.ensure(data,week);
let showLearning=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true;$('save-state').textContent='Saved locally.';}catch{storageOK=false;$('save-state').textContent='Saving unavailable. Changes last only for this visit.';}return storageOK}
if(storageOK)persist();else $('save-state').textContent='Saved data could not be read. Existing storage is untouched; export this visit before leaving.';
let readFailure=!storageOK;
function save(){if(readFailure){$('save-state').textContent='Existing saved data could not be read. This visit is in memory only; export a backup.';return false}return persist()}
function message(text){$('notice').textContent=text;}
function act(fn,success='Saved on this device.'){try{fn();const ok=save();render();message(ok?success:'Changes are in memory only. Export a backup before closing.')}catch(e){message(e.message)}}
function refreshClock(){const next=C.dateKey(appNow());if(next===today){refreshPassiveWindows();updateFocusGlow();return false;}today=next;week=C.weekKey(today);C.ensure(data,week);current=(appNow().getDay()+6)%7;historyWeek=week;save();render();return true}
function option(value,label,selected){return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`}
function areaOptions(selected,none=false){return (none?option('','General action',selected):'')+Object.entries(C.areas).map(([a,t])=>option(a,t,selected)).join('')}
function dateLabel(s){return new Date(s+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function month(){return today.slice(0,7)}
function monthData(m=month()){return data.months[m]||(data.months[m]={goals:[],reviewed:false})}
function switchView(v){refreshClock();view=v;render();message('');}
function nav(){const names=['Today','Execute','Academics','Goals','Coach','Progress'];$('main-nav').innerHTML=names.map(n=>`<button data-view="${n.toLowerCase()}" aria-pressed="${view===n.toLowerCase()}">${n}</button>`).join('');$('date').textContent=appNow().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});$('focus-session-status').textContent=data.focusTimer?'Focus session active':'';$('focus-resume').hidden=!data.focusTimer;$('view').setAttribute('aria-label',names.find(n=>n.toLowerCase()===view));$('month-notice').innerHTML=!monthData().reviewed&&view!=='goals'?`<div class="month-prompt"><p><strong>Your monthly review is ready.</strong> Review last month and choose one meaningful mission. A second is optional.</p><button class="button" data-view="goals">Review monthly goals</button></div>`:''}
function meter(n,total,label){return `<div class="progress"><span>${esc(label)}</span><strong>${n} / ${total} · ${total?Math.round(n*100/total):0}%</strong></div><progress max="${total||1}" value="${n}" aria-label="${esc(label)}"></progress>`}
function plannedSummary(w=week){const s=C.weeklyStats(data,w);return `<div class="week-summary">${meter(s.done,s.total,'Planned tasks this week')}<p class="muted">Week of ${dateLabel(w)} · ${s.skipped} skipped · ${s.rescheduled} rescheduled. Only completed tasks fill this bar.</p></div>`}
function schoolPanel(){const wk=C.ensure(data,week),pending=C.outstanding(data,today).find(t=>t.area&&t.area!=='education');return `<details class="panel"><summary>Coursework finished ahead of schedule?</summary><p class="muted">Confirm all assignments for this week are done. This records the milestone; it does not complete future study blocks.</p><button class="button" data-action="school-toggle">${wk.schoolDone?'Undo coursework-finished milestone':'Confirm coursework finished this week'}</button>${wk.schoolDone||AcademicTracker.workload(data,today).allSubmitted?`<div class="status-note">Coursework is reported finished. Suggested priority: ${esc(pending?pending.title:'Business development or intentional recovery')}. Choose a replacement below.</div><form data-form="replace"><label>Coursework block<select name="day">${option('3','Thursday coursework','3')}${option('5','Saturday college catch-up','3')}</select></label><label>Use the time for<select name="area">${Object.entries(C.areas).filter(([a])=>a!=='education').map(([a,t])=>option(a,t,pending?.area||'business')).join('')}</select></label><button class="primary">Approve replacement block</button><p class="muted">The original is marked skipped with a reason. The new block starts incomplete.</p></form>`:''}</details>`}
function taskRow(t,detail=false,readonly=false){const ended=t.status==='window-ended',complete=t.status==='complete'||ended,meta=ended?'Window Ended':t.passive&&t.status==='incomplete'?'Time window':t.status==='rescheduled'?'Rescheduled to '+dateLabel(t.due):t.status;return `<article class="task" data-task="${esc(t.id)}" data-week="${t.week}"><input type="checkbox" aria-label="${t.passive?'Time window: ':'Complete '}${esc(t.title)}" ${complete?'checked':''} ${readonly||t.passive?'disabled':''} data-check="${esc(t.id)}" data-week="${t.week}"><div class="task-content">${!readonly?`<button class="button coach-task-button" data-task-coach="${esc(refToken('task',t.week,t.id))}" aria-label="Coach Me: ${esc(t.title)}">Coach Me</button>`:''}<div class="time">${esc(t.time)}</div><div class="task-title">${esc(t.title)}</div><span class="badge ${t.status}">${esc(meta)}</span>${t.optional?'<span class="badge">Optional</span>':''}${t.weeklyFocus?'<p class="muted">Supports this week’s Move Forward goal.</p>':''}${!readonly&&t.area==='education'?academicBlock(t):''}${!readonly&&t.day===6&&/Weekly Planning/i.test(t.title)?sundayGoalShortcut(t):''}${t.passive?'<p class="window-note">Time passing does not verify rest or award achievement credit.</p>':''}${!readonly?`<details class="task-details"><summary>More Details</summary><ul>${TaskCoach.guide(academicTask(t)).details.map(line=>`<li>${esc(line)}</li>`).join('')}</ul><p class="muted"><strong>Intended outcome:</strong> ${esc(TaskCoach.guide(academicTask(t)).outcome)}</p></details>`:''}${t.due&&t.due!==t.date?`<p class="muted">Moved from ${dateLabel(t.date)}. Status follows this same task.</p>`:''}${t.reason?`<p class="muted">${esc(t.reason)}</p>`:''}${detail?`<p class="muted">Originally ${dateLabel(t.date)}${t.area?' · '+esc(C.areas[t.area]):''}</p><p class="cue">${esc(t.kind==='task'&&t.id.endsWith('-0')&&[0,2,4].includes(t.day)?'Get home → change clothes → head to Crunch. Track mobility separately below.':t.cue)}</p><button class="button" data-coach="${esc(t.title)}" data-area="${esc(t.area||'organization')}">Help me start</button>`:''}${!readonly?`<details class="task-status"><summary>${detail?'Update status or reschedule':'Manage task'}</summary><form data-form="status" data-id="${esc(t.id)}" data-week="${t.week}"><label>Status<select name="status">${C.statuses.map(s=>option(s,s.charAt(0).toUpperCase()+s.slice(1),t.status)).join('')}</select></label><label>New date, required for rescheduling<input name="due" type="date" min="${today}" value="${esc(t.due||'')}"></label><label>Reason or context<input name="reason" maxlength="240" value="${esc(t.reason||'')}" placeholder="e.g. Work ran late"></label><button class="button">Save task status</button></form><button type="button" class="button collapse-task" data-collapse-task aria-label="Collapse task controls">− Task</button></details>`:''}</div></article>`}
function dayRecords(){const date=C.addDays(week,current),base=C.records(data,week).filter(t=>t.day===current&&!t.retired);const incoming=Object.keys(data.weeks).flatMap(w=>C.records(data,w)).filter(t=>t.status==='rescheduled'&&t.due===date&&!base.some(b=>b.id===t.id&&b.week===t.week));return base.concat(incoming).sort((a,b)=>(a.order??0)-(b.order??0))}
function renderToday(){const d=C.schedule[current],rows=dayRecords().filter(t=>t.kind==='task');document.documentElement.style.setProperty('--accent',d.color);return `<div class="date-line"><p class="small-title">Your day, with room to adapt</p><button class="button" data-action="today">Jump to today</button></div><nav class="tabs" aria-label="Days of the week">${C.schedule.map((d,i)=>`<button class="tab ${i===current?'active':''}" style="--day:${d.color}" aria-label="${d.day}" aria-pressed="${i===current}" data-day="${i}">${d.day.slice(0,3).toUpperCase()}</button>`).join('')}</nav><div id="reset-transition"></div>${plannedSummary()}<div class="day-panel"><div class="dayhead"><span class="eyebrow">${d.day.toUpperCase()} · ${dateLabel(C.addDays(week,current))}</span><h2>${d.theme}</h2></div>${meter(rows.filter(t=>!t.passive&&t.status==='complete').length,rows.filter(t=>!t.passive).length,'Daily planned tasks')}${rows.map(t=>taskRow(t)).join('')}</div><p class="muted">Manage unfinished commitments, mobility, and goal actions in <button class="button" data-view="execute">Execute</button>.</p><details class="panel"><summary>Log an alternative accomplishment</summary><p class="muted">Log a completed activity that replaced your plan. It supports a broad goal without completing any planned task. Use the task checkbox for the original activity to avoid counting it twice.</p><form data-form="activity"><label for="activity-text">What did you accomplish?</label><textarea id="activity-text" name="text" maxlength="600" required placeholder="e.g. Attended boxing instead of upper-body strength"></textarea><div class="actions"><button type="button" class="button" data-action="match">Suggest goal area</button></div><label for="activity-area">Confirm the goal area</label><select id="activity-area" name="area">${areaOptions('fitness')}</select><label>Activity date<input type="date" name="date" required value="${today}" max="${today}"></label><button class="primary">Save alternative activity</button></form></details>${goalPlannerToday()}${skoolPanel()}${adaptationNote()}${academicStudyNote()}${schoolPanel()}`}
function adaptationNote(){const fitness=C.credits(data,week).fitness,pending=C.outstanding(data,today).find(t=>t.area==='mobility');return fitness&&pending?`<div class="status-note">Your fitness work counts. Mobility is still outstanding for ${dateLabel(pending.date)}.<div class="actions"><button class="button" data-coach="Mobility exercises (5–10 min)" data-area="mobility">Help me switch to mobility</button></div></div>`:''}
function monthlyCredits(m){const totals=Object.fromEntries(Object.keys(C.areas).map(a=>[a,0]));Object.keys(data.weeks).forEach(w=>{C.records(data,w).filter(t=>t.status==='complete'&&t.area&&(t.completedDate||t.date).startsWith(m)).forEach(t=>totals[t.area]++);C.ensure(data,w).activities.filter(a=>!a.archived&&a.date.startsWith(m)).forEach(a=>{if(a.area in totals)totals[a.area]++})});return totals}
function goalList(period,key){if(period==='long')return data.longGoals;return period==='month'?monthData(key).goals:C.ensure(data,key).goals}
function renderProgress(){const keys=Object.keys(data.weeks).sort().reverse();if(!keys.includes(historyWeek))historyWeek=week;const w=historyWeek,s=C.weeklyStats(data,w),cr=C.credits(data,w),wk=C.ensure(data,w),patterns=C.patterns(data);return `<h2>See what’s moving.</h2><p class="section-intro">Planned task completion and broad goal progress answer different questions. Alternatives support your goals; they never silently complete the original plan.</p><label>Review a week<select id="history-week">${keys.map(k=>option(k,'Week of '+dateLabel(k),w)).join('')}</select></label><div class="stats"><div class="stat"><strong>${s.done}/${s.total}</strong><span>Planned tasks complete</span></div><div class="stat"><strong>${s.mobility}/${s.habits}</strong><span>Mobility sessions</span></div><div class="stat"><strong>${wk.goals.filter(g=>g.done).length}/${wk.goals.length}</strong><span>Weekly goals complete</span></div></div><p class="muted">${s.skipped} planned tasks skipped · ${s.rescheduled} rescheduled · ${s.activities} alternatives logged${wk.schoolDone?' · Coursework finished milestone confirmed':''}</p><p class="muted">Standard fitness plan: 3 days, Monday upper-body strength, Wednesday boxing with optional lifting, Friday full-body strength. ${C.fitnessDays(data,w)} distinct fitness days recorded this week. Boxing and resistance training earn separate activity credits.</p><details class="panel"><summary>Schedule time zone</summary><form data-form="timezone"><label>IANA time zone<input name="timezone" value="${esc(data.timezone)}" required placeholder="America/Los_Angeles"></label><button class="button">Save time zone</button></form><p class="muted">Reset windows and task clocks use this zone. Default: America/Los_Angeles.</p></details>${academicProgress()}${goalPlannerProgress()}<h3>Broad goal activity credit</h3>${Object.entries(C.areas).map(([a,label])=>`<div class="history-row"><span>${esc(label)}</span> <strong>${cr[a]||0}</strong></div>`).join('')}<p class="muted">One credit per completed relevant task or independent mobility session, plus confirmed alternative activities. Readiness and recovery tasks do not earn workout credit. Don’t log the same original task again as an alternative.</p><h3>Planned task trend</h3>${keys.slice(0,8).reverse().map(k=>{const st=C.weeklyStats(data,k);return `<div class="chart-row">${meter(st.done,st.total,'Week of '+dateLabel(k))}</div>`}).join('')}<h3>Repeated postponements</h3>${patterns.length?patterns.map(([name,n])=>`<div class="status-note">${esc(name)} was rescheduled ${n} times. Try a smaller first action or choose a more realistic time.</div>`).join(''):'<p class="muted">No repeated rescheduling pattern recorded yet.</p>'}<details class="panel"><summary>Skool learning recorded this week</summary>${learningLogRows(data.learningLogs.filter(l=>C.weekKey(l.date)===w))}</details><h3>Weekly accomplishments</h3>${C.records(data,w).filter(t=>t.status==='complete').map(t=>`<div class="log-row">✓ ${esc(t.title)}<p class="muted">${dateLabel(t.completedDate||t.date)} · ${t.kind==='habit'?'Independent mobility':'Planned task'}</p></div>`).join('')}${wk.activities.filter(a=>!a.archived).map(a=>`<div class="log-row">✓ ${esc(a.text)}<p class="muted">${dateLabel(a.date)} · Alternative · ${esc(C.areas[a.area])}</p><button class="button" data-archive="${esc(a.id)}" data-week="${w}">Exclude accidental log</button></div>`).join('')||''}${wk.activities.some(a=>a.archived)?`<details><summary>Excluded logs</summary>${wk.activities.filter(a=>a.archived).map(a=>`<p>${esc(a.text)} <button class="button" data-archive="${esc(a.id)}" data-week="${w}">Restore log</button></p>`).join('')}</details>`:''}<h3>Weekly goals</h3>${goalCards(wk.goals,'week',w,true)}<details class="panel"><summary>Full plan & task statuses</summary><p class="read-only">History view. Use Execute for current tasks; manage older reschedules below.</p>${C.records(data,w).map(t=>taskRow(t,false,true)).join('')}</details>${Object.keys(data.weeks).flatMap(k=>C.records(data,k)).filter(t=>t.status==='rescheduled').length?`<details class="panel"><summary>All rescheduled commitments</summary>${Object.keys(data.weeks).flatMap(k=>C.records(data,k)).filter(t=>t.status==='rescheduled').map(t=>taskRow(t,true)).join('')}</details>`:''}<details class="panel"><summary>Monthly goal history</summary>${Object.keys(data.months).sort().reverse().map(m=>`<h3>${m} · ${data.months[m].goals.filter(g=>g.done).length}/${data.months[m].goals.length} goals complete</h3><p class="muted">${esc(data.months[m].review||'No review note')}</p>${goalCards(data.months[m].goals,'month',m,true)}`).join('')}</details><div class="actions"><button class="button" data-action="export">Export my data backup</button></div><p class="muted">Your backup contains personal notes and progress. Keep it somewhere private. It is not uploaded to GitHub.</p>`}
function monthlyLink(g){const m=g.monthlyMonth||month();return ((data.months[m]||{}).goals||[]).find(x=>x.id===g.monthly)}
function refToken(kind,key,id){return [kind,key,id].join('|')}
function resolveRef(token){const [kind,key,id]=token.split('|');if(kind==='task'){const t=C.records(data,key).find(t=>t.id===id);return t?{...t,kind:'task',week:key}:null}if(kind==='goal'){const g=C.ensure(data,key).goals.find(g=>g.id===id);return g?{...g,kind,week:key}:null}if(kind==='month'){const g=((data.months[key]||{}).goals||[]).find(g=>g.id===id);return g?{...g,kind,month:key}:null}return null}
function actionCard(item,kind='task'){const token=refToken(kind,item.week,item.id),due=item.due||item.date||C.addDays(item.week,6),goal=kind==='goal'?monthlyLink(item):null;return `<article class="action-card"><div><span class="badge ${due<today?'overdue':''}">${item.status==='rescheduled'?'Rescheduled · ':''}${due===today?'Due today':'Planned'} · ${dateLabel(due)}</span><h3>${esc(item.title)}</h3>${kind==='task'?`<details><summary>Action cue${item.optional?' · Optional':''}</summary><p class="cue">${esc(item.cue||'Take one concrete first step.')}</p>${item.optional?'<p class="muted">Shorten, skip with a reason, or reschedule if needed. Mark complete only for the activity you actually finish.</p>':''}</details>`:''}${goal?`<p class="goal-link">Advances: ${esc(goal.title)}</p>`:''}${item.reason?`<p class="muted">${esc(item.reason)}</p>`:''}<div class="actions"><button class="primary" data-start-ref="${esc(token)}">Start</button><button class="button" data-quick="complete" data-ref="${esc(token)}">Complete</button><button class="button" data-quick="skipped" data-ref="${esc(token)}">Skip</button></div><details><summary>Reschedule</summary><form data-form="quick-reschedule" data-ref="${esc(token)}"><label>New date<input type="date" name="due" required min="${today}" value="${due<today?today:due}"></label><label>Reason, optional<input name="reason" maxlength="240" placeholder="A realistic reason or better time"></label><button class="button">Save new date</button></form></details></div></article>`}
function updateFocusGlow(){if(!document.querySelectorAll)return;const now=appNow(),actual=(now.getDay()+6)%7,active=view==='today'&&current===actual,tasks=active?dayRecords().filter(t=>t.kind==='task'):[],focus=active?C.focusSelection(tasks,now):null;document.querySelectorAll('#view .task').forEach(row=>{const task=tasks.find(t=>t.id===row.dataset.task&&t.week===row.dataset.week),late=!!task&&C.isLateBlock(task,now),on=!!focus&&row.dataset.task===focus.id&&row.dataset.week===focus.week,next=on&&focus.mode==='next';row.classList.toggle('focus-glow',on&&!next);row.classList.toggle('next-glow',next);row.classList.toggle('late-glow',late);if(on&&!next)row.setAttribute('aria-current','time');else row.removeAttribute('aria-current');let marker=row.querySelector('.focus-marker');if(on||late){if(!marker){marker=document.createElement('span');marker.className='focus-marker';row.querySelector('.time').appendChild(marker)}marker.textContent=late?'Time block ended · Unfinished':next?'Up Next · Ready when you are':'Focus Glow · Now'}else if(marker)marker.remove()});const hint=$('reset-transition'),next=active?C.resetTransition(data,today,now):null;if(hint)hint.innerHTML=next?`<div class="accent-panel"><p>You already made the commitment. Your reset window is ending. Take just one first step toward ${esc(next.title)}.</p><button class="button" data-start-ref="${esc(refToken('task',next.week,next.id))}">Optional: help me transition</button></div>`:'';}
function renderExecute(){const due=C.outstanding(data,today),habits=due.filter(t=>t.kind==='habit'),tasks=due.filter(t=>t.kind!=='habit'),goals=C.weeklyActions(data,today,true),missed=C.missedThisWeek(data,today),soon=Object.keys(data.weeks).flatMap(w=>C.records(data,w)).filter(t=>t.status==='rescheduled'&&t.due>today);return `<h2>One commitment at a time.</h2><p class="section-intro">An action queue, not another timetable. Start with a goal action, a small habit, or a commitment for today. See the full schedule in Today.</p><div class="stats"><div class="stat"><strong>${goals.length}</strong><span>Open weekly actions</span></div><div class="stat"><strong>${habits.length}</strong><span>Small habits due</span></div><div class="stat"><strong>${tasks.length}</strong><span>Other commitments due</span></div></div>${academicQueue()}<h3>Move a monthly priority forward</h3>${goals.length?goals.map(g=>actionCard(g,'goal')).join(''):'<p class="empty">Choose a monthly outcome, then approve a weekly action toward it.</p><button class="button" data-view="goals">Choose goals & actions</button>'}<h3>Small habits, clear finish lines</h3>${habits.length?habits.map(t=>actionCard(t)).join(''):'<p class="empty">No small habits are due right now.</p>'}<h3>Outstanding commitments</h3>${tasks.length?tasks.slice(0,3).map(t=>actionCard(t)).join(''):'<p class="empty">No other commitments planned for today.</p>'}${tasks.length>3?`<details class="panel"><summary>${tasks.length-3} more outstanding commitments</summary>${tasks.slice(3).map(t=>actionCard(t)).join('')}</details>`:''}${soon.length?`<details class="panel"><summary>${soon.length} upcoming rescheduled commitments</summary>${soon.map(t=>actionCard(t)).join('')}</details>`:''}${missed.length?`<details class="panel missed-week"><summary>Missed this week · ${missed.length}</summary><p class="muted">These dates have passed. This is a record, not a catch-up list. Next week starts fresh; your history stays saved.</p>${missed.map(t=>`<div class="missed-item"><strong>${esc(t.title)}</strong><span>${dateLabel(t.due||t.date)} · Missed</span></div>`).join('')}</details>`:''}<div class="actions"><button class="button" data-action="open-learning">Record Skool learning</button><button class="button" data-view="today">Open full schedule</button></div><p class="muted">Start opens a short transition. Only Complete records completion. Skip and Reschedule keep an honest record.</p>`}
function goalForm(g,period,key){const monthly=monthData().goals.filter(m=>!m.done||m.id===g.monthly);return `<form data-form="goal-edit" data-id="${esc(g.id)}" data-period="${period}" data-key="${key}"><label>Goal title<input name="title" value="${esc(g.title)}" maxlength="180" required></label>${period!=='long'?`<label>Goal area<select name="area">${areaOptions(g.area)}</select></label>${period==='month'?`<label>Milestone unit<input name="unit" maxlength="80" value="${esc(g.unit||'milestones')}"></label><label>Progress tracking<select name="metric">${option('milestones','Documented achievement milestones',g.metric||'activities')}${option('activities','Existing broad-area activity tracking',g.metric||'activities')}</select></label>`:''}<label>${period==='month'?'Milestone target':'Target'}<input name="target" type="number" min="1" max="999" value="${g.target}" required></label><label>Long-term ambition<select name="parent">${option('','No link yet',g.parent)}${data.longGoals.map(l=>option(l.id,l.title,g.parent)).join('')}</select></label>${period==='week'?`<label>Monthly outcome<select name="monthly">${option('','Existing action without a link',g.monthly)}${monthly.map(m=>option(m.id,m.title,g.monthly)).join('')}</select></label><label>Due date<input name="due" type="date" value="${esc(g.due||C.addDays(key,6))}" required></label><label>First small action<input name="cue" value="${esc(g.cue||'')}" maxlength="240"></label>`:''}`:''}<div class="actions"><button class="button">Save goal changes</button>${period!=='long'?`<button type="button" class="button" data-remove-goal="${esc(g.id)}" data-period="${period}" data-key="${key}">Remove goal</button>`:''}</div></form>`}
function goalCards(list,period,key,readonly=false){const counts=period==='month'?monthlyCredits(key):period==='week'?C.credits(data,key):{};return list.length?list.map(g=>{const milestone=g.metric==='milestones',evidence=(g.milestones||[]).filter(e=>!e.archived),parent=data.longGoals.find(l=>l.id===g.parent),linked=period==='week'?monthlyLink(g):null;return `<article class="goal-card"><label class="goal-check"><input type="checkbox" data-goal="${esc(g.id)}" data-period="${period}" data-key="${key}" ${g.done?'checked':''} ${readonly?'disabled':''}><strong>${esc(g.title)}</strong></label>${period==='month'?milestone?`${meter(Math.min(evidence.length,g.target),g.target,'Documented achievement milestones')}<p class="muted">${esc(g.unit||'Milestones')} · Task starts and unrelated routine activity do not fill this bar. Confirm the goal checkbox when the outcome is actually achieved.</p>`:`<p class="muted">Existing goal preserved with its original activity-based tracking. You can edit it to track an achievement instead.</p>${meter(Math.min(counts[g.area]||0,g.target),g.target,'Legacy supporting activity target')}`:period==='week'?`<span class="badge ${C.goalStatus(g)}">${C.goalStatus(g)}</span><p class="muted">Due ${dateLabel(g.due||C.addDays(key,6))}. Completing this action does not automatically finish its monthly goal.</p>`:''}${period!=='long'?`<p class="goal-link">Long-term: ${esc(parent?.title||'No link selected')}${period==='week'?'<br>Monthly: '+esc(linked?.title||'No current monthly link'):''}</p>`:''}${period==='month'&&milestone?`${evidence.map(e=>`<div class="log-row">${esc(e.note)}<p class="muted">${dateLabel(e.date)}</p>${!readonly?`<button class="button" data-exclude-evidence="${esc(e.id)}" data-goal-id="${esc(g.id)}" data-month="${key}">Exclude mistaken milestone</button>`:''}</div>`).join('')}${(g.milestones||[]).some(e=>e.archived)&&!readonly?`<details><summary>Excluded milestone records</summary>${g.milestones.filter(e=>e.archived).map(e=>`<p>${esc(e.note)} <button class="button" data-exclude-evidence="${esc(e.id)}" data-goal-id="${esc(g.id)}" data-month="${key}">Restore milestone</button></p>`).join('')}</details>`:''}${!readonly?`<details><summary>Record an achieved milestone</summary><form data-form="milestone" data-goal-id="${esc(g.id)}" data-month="${key}"><label>What did you finish or demonstrate?<textarea name="note" required maxlength="700" placeholder="Describe the result, not just time spent"></textarea></label><label>Date<input type="date" name="date" required max="${today}" value="${today}"></label><button class="primary">Save milestone</button></form></details>`:''}`:''}${period==='week'&&!readonly&&!['complete','skipped'].includes(C.goalStatus(g))?`<button class="button" data-start-ref="${esc(refToken('goal',key,g.id))}">Start this action</button>`:''}${!readonly?`<details><summary>Edit goal</summary>${goalForm(g,period,key)}</details>`:''}</article>`}).join(''):'<p class="empty">No goals approved yet. Start with a suggestion or add your own.</p>'}
function suggestions(period){const rec=C.recommendations(data,period,today);return rec.length?`<div class="suggestions">${rec.map((g,i)=>`<article class="suggestion"><span class="badge">${period==='month'?'Possible monthly achievement':'Suggested weekly step'}</span><h3>${esc(g.title)}</h3><p class="muted">${period==='week'?'Advances: '+esc(monthlyLink(g)?.title||'your selected monthly goal'):'Supports '+esc(data.longGoals.find(l=>l.id===g.parent)?.title||C.areas[g.area])}${g.achievement==='forex'?'<br>Hypothetical or demo exercises count. Document risk limits, invalidation, and when to pass; no live trades are required.':''}</p><button class="primary" data-adopt="${i}" data-period="${period}">Approve ${period==='month'?'goal':'weekly action'}</button></article>`).join('')}</div>`:'<p class="empty">Select an unfinished monthly goal first. Weekly suggestions will then point to that specific outcome.</p>'}
function addGoalForm(period){const monthly=monthData().goals.filter(m=>!m.done);return `<details class="panel"><summary>Add a custom ${period==='month'?'monthly goal':'weekly action'}</summary><form data-form="goal-add" data-period="${period}"><label>${period==='month'?'Achievement you want to finish':'Specific action for this week'}<input name="title" required maxlength="180" placeholder="${period==='month'?'e.g. Publish a finished portfolio page':'e.g. Draft and test my portfolio contact page'}"></label><label>Goal area<select name="area">${areaOptions('business')}</select></label><label>${period==='month'?'Milestone target':'Target'}<input name="target" type="number" min="1" max="999" value="1" required></label><label>Long-term ambition<select name="parent">${data.longGoals.map(l=>option(l.id,l.title,'long-business')).join('')}</select></label>${period==='week'?`<label>Monthly outcome<select name="monthly" required>${option('','Choose a monthly goal','')}${monthly.map(m=>option(m.id,m.title,'')).join('')}</select></label><label>Due date<input type="date" name="due" required min="${today}" value="${C.addDays(week,6)}"></label><label>First small action<input name="cue" maxlength="240" placeholder="e.g. Open the project and create one page"></label>${!monthly.length?'<p class="muted">Approve a monthly outcome first.</p>':''}`:''}<button class="primary" ${period==='week'&&!monthly.length?'disabled':''}>Add ${period==='month'?'monthly goal':'weekly action'}</button></form></details>`}
function renderLegacyGoals(){const m=month(),md=monthData(),prev=data.months[C.addDays(m+'-01',-1).slice(0,7)];return `<h2>Build something worth finishing.</h2><p class="section-intro">Choose up to three meaningful monthly achievements. Keep gym, mobility, assignments, and chores in your schedule. Weekly actions turn your chosen outcomes into specific next steps.</p>${!md.reviewed?`<div class="month-prompt"><h3>Monthly review · ${m}</h3><p class="muted">${prev?`${prev.goals.filter(g=>g.done).length} of ${prev.goals.length} goals completed last month.`:'Choose outcomes that move your life forward this month.'}</p><label>What worked, and what needs to change?<textarea id="month-review" maxlength="1000">${esc(md.review||'')}</textarea></label><button class="primary" data-action="review">Save monthly review</button></div>`:''}<h3>Choose your monthly achievements</h3>${suggestions('month')}<h3>Your selected monthly goals · ${md.goals.length} of 3</h3>${goalCards(md.goals,'month',m)}${addGoalForm('month')}<h3>Weekly steps toward your selected goals</h3>${suggestions('week')}<h3>Your approved weekly actions</h3>${goalCards(C.ensure(data,week).goals,'week',week)}${addGoalForm('week')}<details class="panel"><summary>Long-term ambitions & priority areas</summary><p class="muted">Link each monthly outcome to the ambition it serves. Priority areas move matching suggestions first; all achievement choices remain available.</p><div class="priority-list">${Object.entries(C.areas).map(([a,label])=>`<label><input type="checkbox" data-priority="${a}" ${data.priorities.includes(a)?'checked':''}>${esc(label)}</label>`).join('')}</div>${goalCards(data.longGoals,'long','')}</details>`}
function physicalAction(area){return {learning:'Open your chosen Skool community and select one lesson.',mobility:'Put both feet on your mat and begin one mobility movement.',fitness:'Put on your training shoes.',education:'Open your course page and read the first question.',business:'Open your website project and create one small draft.',financial:'Open your practice journal and write down a risk limit.',creative:'Pick up your camera or open one photo.',relationships:'Open your calendar and choose one person to contact.',organization:'Stand up and put one item where it belongs.',recovery:'Put your phone down and sit somewhere comfortable.'}[area]||'Stand up and open the one item you need.'}
function openTaskCoach(token){let task=resolveRef(token);if(!task)return;if(task.kind==='goal'){const m=GoalPlanner.findMonthly(data,task.monthlyMonth||month(),task.monthly);task={...task,mission:m?{title:m.title,finishLine:m.finishLine||m.title}:null};}if(task.area==='education'){const x=AcademicTracker.workload(data,task.due||task.date).next;if(x)task={...task,assignment:x,title:task.title+' · '+x.title}}data.taskCoach={active:true,task:{...task,ref:token},mode:null,stage:'modes',step:0,from:null,target:'',wait:'',note:''};save();switchView('coach');window.scrollTo(0,0)}
function coachTaskReturn(){const c=data.taskCoach,t=c.task,date=t.due||t.date;data.taskCoach.active=false;if(t.kind==='goal'){focusSetup=null;save();goalsPage='weekly';goalsWeek=t.week;switchView('goals');window.scrollTo(0,0);return;}if(t.kind==='academic'){save();switchView('academics');window.scrollTo(0,0);return;}const displayWeek=C.weekKey(date);if(displayWeek===week)current=(new Date(date+'T12:00:00').getDay()+6)%7;save();switchView('today');window.scrollTo(0,0)}
function recordCoachStart(){const c=data.taskCoach;if(!c.startRecorded){data.starts.push({title:c.task.title,area:c.task.area||C.suggest(c.task.title),date:today,ref:{kind:c.task.kind||'task',id:c.task.id,week:c.task.week}});c.startRecorded=true}c.stage='done';save();render()}
function renderTaskCoach(){const c=data.taskCoach,t=c.task,modes={switch:'Help Me Switch',start:'Help Me Start',focus:'Help Me Focus',overwhelmed:"I’m Overwhelmed"},g=TaskCoach.guide(t);let body='';
if(c.stage==='modes')body=`<h3>What would help right now?</h3><div class="task-coach-modes">${Object.entries(modes).map(([k,label])=>`<button class="primary" data-task-mode="${k}">${label}</button>`).join('')}</div><p class="muted">Switch: leave another activity. Start: take the first step. Focus: return to work you already began. Overwhelmed: reduce the load.</p>`;
else if(c.stage==='situation')body=`<h3>What are you doing right now?</h3><div class="task-coach-modes">${Object.entries(TaskCoach.situations).map(([k,label])=>`<button class="button" data-task-from="${k}">${label}</button>`).join('')}</div>`;
else if(c.stage==='focus')body=`<h3>One target. One short session.</h3><p>You made the commitment. Put unrelated tabs and distractions aside. Choose one small target you can work on now.</p><form data-form="task-focus"><label>My immediate target<input name="target" required maxlength="240" value="${esc(c.target)}" placeholder="e.g. Draft the first discussion paragraph"></label><label>Focus session<select name="minutes">${[10,15,25].map(n=>option(n,n+' minutes',c.minutes||10)).join('')}</select></label><button class="primary">Start focus timer</button></form><p class="muted">The countdown uses an end time and catches up when reopened. No background sound or notification is promised.</p>`;
else if(c.stage==='timer')body=`<h3>${esc(c.target)}</h3><p>Work on this target. You already started; there is no need to repeat switching steps.</p><p id="focus-clock" class="focus-clock"></p><div class="actions"><button class="primary" data-task-flow="return">Return to my task</button><button class="button" data-task-flow="stop-timer">Stop focus session</button></div><p class="muted">Timer continues on this device when you return to Today. It does not complete the task.</p>`;
else if(c.stage==='reduce')body=`<h3>Choose what matters for the next two minutes.</h3><form data-form="task-reduce"><label>One small priority within this task<input name="target" maxlength="240" value="${esc(c.target)}" placeholder="e.g. Read the first question"></label><label>What can reasonably wait? Optional<input name="wait" maxlength="400" value="${esc(c.wait)}" placeholder="e.g. Formatting the final submission"></label><button class="primary">Show one manageable step</button></form>`;
else if(c.stage==='steps'){const steps=TaskCoach.steps(t,c.mode,c.from,c.target),i=Math.min(c.step,steps.length-1);body=`<span class="step-number">STEP ${i+1} OF ${steps.length} · ${esc(modes[c.mode])}</span><p class="coach-copy">You made the commitment. Now execute. Just take this one step.</p><h3 class="micro-action">${esc(steps[i])}</h3>${c.wait?`<p class="muted">Can wait: ${esc(c.wait)}</p>`:''}${c.from==='project'&&i===0?`<label>Save My Place, optional<input id="task-return-note" maxlength="500" value="${esc(c.note)}" placeholder="Where will you pick up this project later?"></label>`:''}<div class="actions">${i>0?'<button class="button" data-task-flow="previous">Previous step</button>':''}<button class="primary" data-task-flow="next">${i===steps.length-1?'I have started':'Done, next step'}</button>${i<steps.length-1?'<button class="button" data-task-flow="next">Already done</button>':''}</div><p class="muted">These are transition steps. They never check off your scheduled activity.</p>`;}
else body=`<h3>You have started.</h3><p>Keep the next part manageable. Your planned task stays incomplete until you finish it and explicitly mark it complete.</p><button class="primary" data-task-flow="return">Return to my task</button>`;
return `<h2>${esc(t.title)}</h2><p class="section-intro">${t.kind==='academic'?esc(AcademicTracker.course.title):esc(t.time||'Flexible time')+' · '+dateLabel(t.due||t.date)}${t.optional?' · Optional activity':''}</p>${t.mission?`<p class="goal-link">Monthly mission: ${esc(t.mission.title)} · Finish line: ${esc(t.finishLine||t.title)}</p>`:''}${t.assignment?`<p class="muted">Assignment deadline: ${esc(academicDeadline(t.assignment))} · ${esc(t.assignment.status)}. Submission is recorded separately.</p>`:''}<section class="accent-panel task-coach-panel">${body}</section><div class="actions"><button class="button" data-task-flow="modes">Choose another kind of help</button><button class="button" data-task-flow="return">Back to task</button></div>${data.park?`<details class="panel"><summary>Your saved place</summary><p>${esc(data.park.note)}</p>${data.park.next?`<p>Pick up at: ${esc(data.park.next)}</p>`:''}</details>`:''}<p class="muted">Task-specific, rule-based guidance. Starts, timer sessions, and completed activities are tracked separately.</p>`}
function handleTaskCoachClick(b){if(b.dataset.focusResume!==undefined&&data.focusTimer){const timer=data.focusTimer;data.taskCoach={active:true,task:timer.task,mode:'focus',stage:'timer',target:timer.target,startRecorded:true};save();switchView('coach');return true}if(b.dataset.taskCoach){openTaskCoach(b.dataset.taskCoach);return true}if(b.dataset.taskMode){const c=data.taskCoach;c.mode=b.dataset.taskMode;c.step=0;c.from=null;c.stage=c.mode==='switch'?'situation':c.mode==='focus'?'focus':c.mode==='overwhelmed'?'reduce':'steps';save();render();return true}if(b.dataset.taskFrom){const c=data.taskCoach;c.from=b.dataset.taskFrom;c.step=0;c.stage='steps';save();render();return true}if(b.dataset.taskFlow){const c=data.taskCoach;switch(b.dataset.taskFlow){case 'return':coachTaskReturn();break;case 'modes':c.stage='modes';save();render();break;case 'previous':c.step=Math.max(0,c.step-1);save();render();break;case 'stop-timer':data.focusTimer=null;c.stage='focus';save();render();break;case 'next':{if(c.from==='project'&&c.step===0){const input=$('task-return-note');c.note=input?input.value.trim():'';if(c.note)data.park={note:c.note,next:c.note,date:today}}const steps=TaskCoach.steps(c.task,c.mode,c.from,c.target);if(c.step>=steps.length-1)recordCoachStart();else{c.step++;save();render()}break}}return true}if(b.dataset.collapseTask!==undefined){const details=b.closest('.task-status');if(details)details.open=false;return true}return false}
function handleTaskCoachSubmit(f,v){const c=data.taskCoach;if(f.dataset.form==='task-focus'){if(!v.target.trim()){message('Choose one immediate target.');return true}const minutes=+v.minutes;if(![10,15,25].includes(minutes))return true;c.target=v.target.trim();c.minutes=minutes;c.stage='timer';data.focusTimer={task:{...c.task},target:c.target,endsAt:Date.now()+minutes*60000};if(!c.startRecorded){data.starts.push({title:c.task.title,area:c.task.area||C.suggest(c.task.title),date:today,ref:{kind:c.task.kind||'task',id:c.task.id,week:c.task.week}});c.startRecorded=true}save();render();return true}if(f.dataset.form==='task-reduce'){c.target=v.target.trim();c.wait=v.wait.trim();c.step=0;c.stage='steps';save();render();return true}if(f.dataset.form==='timezone'){if(!C.validTimezone(v.timezone)){message('Enter a valid IANA time zone, such as America/Los_Angeles.');return true}data.timezone=v.timezone;save();refreshClock();render();message('Local schedule time zone saved. No task completion was changed.');return true}return false}
function tickFocusTimer(){const timer=data.focusTimer,seconds=TaskCoach.remaining(timer);const clock=$('focus-clock');if(clock&&seconds!==null)clock.textContent=seconds?String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'):'Session ended. Review your progress.';const status=$('focus-session-status');if(status)status.textContent=timer?(seconds?'Focus session · '+Math.ceil(seconds/60)+' min remaining · '+timer.target:'Focus session ended · '+timer.target):''}

function renderCoach(){if(data.taskCoach?.active)return renderTaskCoach();const c=data.coach,step=Math.min(c.step||0,2),modes={stuck:'I’m stuck',switch:'Switch activities',early:'Finished early',unfinished:'Unfinished commitments',neglected:'Monthly priorities'},mode=c.mode||'stuck',choices=C.coachOptions(data,today,mode);const park=data.park?`<details class="panel"><summary>Your saved place</summary><p>${esc(data.park.note||'Current activity saved')}${data.park.next?'<br>Pick up at: '+esc(data.park.next):''}</p><button class="button" data-action="resume">I returned to my saved place</button></details>`:'';return `<h2>Stuck? Choose one next move.</h2><p class="section-intro">Tell the Coach what you need. It uses your unfinished commitments, linked weekly actions, and monthly goals to suggest a manageable first step.</p>${c.active?`<div class="accent-panel"><span class="step-number">${['1 · SAVE YOUR PLACE','2 · MAKE THE SWITCH','3 · BEGIN THE TASK'][step]}</span><h3>${esc(c.title)}</h3><p class="coach-copy">${step===0?'You made the commitment. Now execute. You’re not giving up your whole evening. Save where you are so you can return.':step===1?'You made the commitment. Now execute. Just invest the next ten minutes. '+esc(c.cue||physicalAction(c.area)):'You made the commitment. Keep the first step small. Begin for five minutes, then decide what comes next.'}</p>${step===0?`<p class="muted">Optional: park an enjoyable activity before switching.</p><label>What are you doing now?<input id="park-note" maxlength="500" value="${esc(data.park?.note||'')}" placeholder="e.g. Working on a creative project"></label><label>Where will you pick up later?<input id="park-next" maxlength="500" value="${esc(data.park?.next||'')}" placeholder="e.g. Finish the opening scene"></label>`:''}<div class="actions"><button class="primary" data-action="coach-next">${['Save my place & show the first step','I made the switch','I have started'][step]}</button><button class="button" data-action="coach-choices">Back to choices</button><button class="button" data-action="coach-reset">Restart transition</button></div><p class="muted">Starting will be recorded separately. Nothing is marked complete here.</p></div>`:`<h3>What do you need help with?</h3><div class="coach-modes">${Object.entries(modes).map(([k,label])=>`<button class="${k===mode?'primary':'button'}" data-coach-mode="${k}" aria-pressed="${k===mode}">${label}</button>`).join('')}</div><p class="muted">${mode==='early'?'You have time back. Choose an unfinished priority or intentional recovery.':mode==='neglected'?'These unfinished outcomes have no linked progress recorded in the past seven days. This reflects your logs, not assumptions about your effort.':'Choose one suggestion below. You can save your place and get a single physical action.'}</p>${choices.length?choices.map((x,i)=>`<article class="choice-card"><h3>${esc(x.title)}</h3><p class="muted">${esc(x.reason)}</p><p><strong>First step:</strong> ${esc(x.cue||physicalAction(x.area))}</p><button class="primary" data-choose-next="${i}">Choose this next action</button></article>`).join(''):'<p class="empty">No matching unfinished items are recorded. Choose a task of your own below.</p>'}${mode==='early'?'<button class="button" data-action="early-schedule">Adjust a freed coursework block</button>':''}<details class="panel"><summary>Choose my own next task</summary><form data-form="coach-custom"><label>What will you work on?<input name="title" maxlength="180" required placeholder="Name one task"></label><label>Area<select name="area">${areaOptions('business')}</select></label><label>One physical first step, optional<input name="cue" maxlength="240" placeholder="e.g. Open the project and create one page"></label><button class="primary">Help me transition</button></form></details>`}${park}<details class="panel"><summary>How Coach works & recent starts</summary><p class="muted">Rule-based suggestions use saved tasks, due dates, selected goals, milestones and starts. There is no AI or account integration. Choose a suggestion, optionally save your place, make the physical switch, and begin. Starts never complete tasks or goals.</p>${data.starts.slice(-5).reverse().map(s=>`<p class="muted">${dateLabel(s.date)} · ${esc(s.title)} · Started only</p>`).join('')||'<p class="muted">No starts recorded yet.</p>'}</details>`}
function learningFields(entry={}){return `<label>Community or course name<input name="community" required maxlength="180" value="${esc(entry.community||'')}" placeholder="Enter the community you actually use"></label><label>Lesson or module<input name="lesson" required maxlength="180" value="${esc(entry.lesson||'')}"></label><label>Progress through this lesson or module (%)<input name="progress" type="number" required min="0" max="100" value="${entry.progress??0}"></label><label>What I learned<textarea name="learned" required maxlength="1200">${esc(entry.learned||'')}</textarea></label><label>One practical action based on the lesson<textarea name="action" required maxlength="500">${esc(entry.action||'')}</textarea></label><label>Learning date<input type="date" name="date" max="${today}" required value="${entry.date||today}"></label>`}
function learningLogRows(rows){return rows.length?rows.slice().reverse().map(l=>`<article class="log-row"><h3>${esc(l.community)}</h3><p>${esc(l.lesson)} · ${l.progress}%</p><p class="muted">${dateLabel(l.date)} · Manual entry</p><p><strong>Learned:</strong> ${esc(l.learned)}</p><p><strong>Apply it:</strong> ${esc(l.action)}</p><details><summary>Edit learning record</summary><form data-form="learning-edit" data-id="${esc(l.id)}">${learningFields(l)}<button class="button">Save learning changes</button></form></details><details><summary>Turn the practical step into a weekly action</summary><form data-form="learning-action" data-id="${esc(l.id)}"><label>Monthly outcome<select name="monthly" required>${option('','Choose a monthly goal','')}${monthData().goals.filter(m=>!m.done).map(m=>option(m.id,m.title,'')).join('')}</select></label><label>Due date<input type="date" name="due" required min="${today}" value="${C.addDays(week,6)}"></label><button class="primary">Approve linked weekly action</button></form><p class="muted">Choose a monthly goal first. Logging a lesson by itself never completes a task or goal.</p></details></article>`).join(''):'<p class="muted">No Skool learning logged yet. Enter your own course and lesson details.</p>'}
function skoolPanel(){const wk=C.ensure(data,week),slot=C.records(data,week).find(t=>t.id==='2-3'),locked=slot.status!=='incomplete';return `${current===2?`<div class="panel"><label>Wednesday 8–9 PM focus<select id="weekly-skill-choice" ${locked?'disabled':''}>${option('skool','Skool Skill Development',slot.slot||'photography')}${option('photography','Photography / creative development',slot.slot||'photography')}</select></label><p class="muted">Choose either focus for this week. Completed or rescheduled records keep their original labels.</p></div>`:''}<details class="panel" id="learning-panel" ${showLearning?'open':''}><summary>Skool learning log</summary><p class="muted">Manual notes only. Mission Control does not read or synchronize your Skool or Pindrop accounts.</p><form data-form="learning">${learningFields()}<button class="primary">Save learning record</button></form><p class="muted">Lesson progress is a note, not automatic completion credit. Mark the scheduled block complete separately when finished.</p>${learningLogRows(data.learningLogs.filter(l=>C.weekKey(l.date)===week))}</details>`}
function setQuick(token,status,due,reason){const x=resolveRef(token);if(!x)throw Error('This commitment is no longer available.');if(x.kind==='goal')C.setGoalStatus(data,x.week,x.id,status,due,reason,today);else C.setStatus(data,x.week,x.id,status,due,reason,today)}
function beginTransition(x){if(data.taskCoach)data.taskCoach.active=false;const area=x.area||(/recovery/i.test(x.title)?'recovery':C.suggest(x.title));const cue=x.kind==='task'?(/Post-Work Reset/.test(x.title)?'Take your uniform off and put it away.':x.cue||physicalAction(area)):(x.cue||physicalAction(area));data.coach={title:x.title,area,cue,step:0,active:true,mode:data.coach.mode||'stuck',ref:x.kind?{kind:x.kind,id:x.id,week:x.week,month:x.month}:null};save();switchView('coach')}
function handleRefinedClick(b){if(handleGoalsClick(b))return true;if(handleAcademicClick(b))return true;if(handleTaskCoachClick(b))return true;if(b.dataset.startRef){const x=resolveRef(b.dataset.startRef);if(x){if(x.area==='education'||x.kind==='goal')openTaskCoach(b.dataset.startRef);else beginTransition(x)}return true}if(b.dataset.quick){act(()=>setQuick(b.dataset.ref,b.dataset.quick,null,b.dataset.quick==='skipped'?'Skipped from action queue':''),b.dataset.quick==='complete'?'Commitment completed. Monthly goals still require their own outcome confirmation.':'Commitment skipped, not completed.');return true}if(b.dataset.coachMode){data.coach.mode=b.dataset.coachMode;data.coach.active=false;save();render();return true}if(b.dataset.chooseNext!==undefined){const x=C.coachOptions(data,today,data.coach.mode||'stuck')[+b.dataset.chooseNext];if(x)beginTransition(x);return true}if(b.dataset.excludeEvidence){act(()=>{const goal=monthData(b.dataset.month).goals.find(g=>g.id===b.dataset.goalId),entry=goal.milestones.find(e=>e.id===b.dataset.excludeEvidence);entry.archived=!entry.archived},'Milestone inclusion updated. Its record is retained.');return true}switch(b.dataset.action){case 'open-learning':current=2;showLearning=true;switchView('today');return true;case 'early-schedule':switchView('today');message('Open “Coursework finished ahead of schedule?” and approve a replacement block.');return true;case 'coach-choices':data.coach.active=false;save();render();return true;case 'coach-reset':act(()=>{data.coach.step=0;data.coach.active=true},'Transition restarted. Your saved place is kept.');return true;case 'coach-next':{const last=data.coach.step===2;act(()=>{const c=data.coach;if(c.step===0){const note=$('park-note').value.trim(),next=$('park-next').value.trim();if(note||next)data.park={note,next,date:today};c.step=1}else if(c.step===1)c.step=2;else{data.starts.push({title:c.title,area:c.area,date:today,ref:c.ref});c.step=0;c.active=false}},last?'Start recorded. The commitment remains incomplete until you finish it.':'Take just the next physical action.');return true}}return false}
function handleRefinedChange(el){if(handleGoalsChange(el))return true;if(el.dataset.academicStep!==undefined){act(()=>{const x=AcademicTracker.items(data).find(x=>x.id===el.dataset.academicId),checked=new Set(x.checked);el.checked?checked.add(+el.dataset.academicStep):checked.delete(+el.dataset.academicStep);AcademicTracker.update(data,x.id,{checked:[...checked]})},'Preparation step saved. Submission status is unchanged.');const details=document.querySelector('[data-assignment="'+el.dataset.academicId+'"] .academic-details');if(details)details.open=true;return true}if(el.id==='weekly-skill-choice'){act(()=>{const t=C.records(data,week).find(t=>t.id==='2-3');if(t.status!=='incomplete')throw Error('Existing recorded commitments keep their original focus.');C.ensure(data,week).creativeChoice=el.value},'Wednesday focus changed for this week. No completion credit was added.');return true}return false}
function handleRefinedSubmit(f,v){if(handleGoalsSubmit(f,v))return true;if(handleAcademicSubmit(f,v))return true;switch(f.dataset.form){case 'quick-reschedule':act(()=>setQuick(f.dataset.ref,'rescheduled',v.due,v.reason));return true;case 'coach-custom':beginTransition({title:v.title,area:v.area,cue:v.cue||physicalAction(v.area)});return true;case 'milestone':act(()=>{validatePastDate(v.date);C.logMilestone(data,f.dataset.month,f.dataset.goalId,v.note,v.date)},'Milestone recorded. Confirm the outcome checkbox only when the goal is achieved.');return true;case 'learning':case 'learning-edit':act(()=>{validatePastDate(v.date);C.logLearning(data,{...v,...(f.dataset.id?{id:f.dataset.id}:{})});showLearning=true},'Learning note saved. No task or goal was automatically completed.');return true;case 'learning-action':act(()=>{const log=data.learningLogs.find(l=>l.id===f.dataset.id),g=monthData().goals.find(g=>g.id===v.monthly&&!g.done);if(!g)throw Error('Choose an unfinished monthly goal.');if(!v.due||v.due<today)throw Error('Choose a due date today or later.');if(C.ensure(data,week).goals.some(a=>a.sourceLearning===log.id&&a.monthly===g.id))throw Error('That practical step is already linked to this goal this week.');C.adoptGoal(data,'week',week,{title:log.action,area:g.area,parent:g.parent,monthly:g.id,monthlyMonth:month(),due:v.due,target:1,metric:'action',sourceLearning:log.id,cue:'Open your notes for '+log.lesson+' and do the first practical step.'})},'Practical step approved as a linked weekly action.');return true}return false}
function validatePastDate(date){if(!date||date>today||C.dateKey(new Date(date+'T12:00:00'))!==date)throw Error('Choose a valid date today or earlier.')}

let passiveSignature='';
function passiveStateSignature(){return C.records(data,week).filter(t=>t.passive).map(t=>t.id+':'+t.status).join('|')}
function refreshPassiveWindows(){const next=passiveStateSignature();if(next!==passiveSignature){passiveSignature=next;if(['today','execute','progress'].includes(view))render()}}
function render(){passiveSignature=passiveStateSignature();nav();$('view').innerHTML=({today:renderToday,execute:renderExecute,goals:renderGoals,coach:renderCoach,progress:renderProgress,academics:renderAcademics}[view])();updateFocusGlow();tickFocusTimer()}
function startCoach(title,area){beginTransition({title,area})}
$('enter').onclick=()=>{refreshClock();current=(appNow().getDay()+6)%7;view='today';$('landing').classList.add('hidden');$('dashboard').classList.remove('hidden');render();window.scrollTo(0,0)};
$('back').onclick=()=>{$('dashboard').classList.add('hidden');$('landing').classList.remove('hidden');window.scrollTo(0,0)};
$('dashboard').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(refreshClock()){message('A new day is loaded. Review the current plan before updating it.');return;}if(handleRefinedClick(b))return;if(b.dataset.view){if(b.dataset.view==='goals'){goalsPage='home';goalDraft=null;weeklySetup=null;focusSetup=null}switchView(b.dataset.view);return}if(b.dataset.day!==undefined){current=+b.dataset.day;render();return}if(b.dataset.coach){startCoach(b.dataset.coach,b.dataset.area);return}if(b.dataset.adopt!==undefined){const p=b.dataset.period;act(()=>{const g=C.recommendations(data,p,today)[+b.dataset.adopt];if(goalList(p,p==='month'?month():week).some(x=>x.title===g.title))throw Error('That suggestion is already approved. Edit it below.');C.adoptGoal(data,p,p==='month'?month():week,g)},'Recommendation approved. You can adjust its title, target, and links.');return}if(b.dataset.removeGoal){act(()=>{const list=goalList(b.dataset.period,b.dataset.key),i=list.findIndex(g=>g.id===b.dataset.removeGoal);if(i>=0)list.splice(i,1)},'Goal removed. Completed task and activity history remains.');return}if(b.dataset.archive){act(()=>{const a=C.ensure(data,b.dataset.week).activities.find(a=>a.id===b.dataset.archive);if(a)a.archived=!a.archived});return}switch(b.dataset.action){case 'today':current=(appNow().getDay()+6)%7;render();break;case 'match':{const text=$('activity-text').value.trim();if(!text){message('Describe the completed activity first.');break}$('activity-area').value=C.suggest(text);message('Goal area suggested. Confirm it before saving. No tasks have been completed.');break}case 'school-toggle':act(()=>{const wk=C.ensure(data,week);wk.schoolDone=!wk.schoolDone},'Coursework milestone updated. Task statuses are unchanged.');break;case 'review':act(()=>{monthData().review=$('month-review').value.trim();monthData().reviewed=true},'Monthly review saved. Approve or adjust your three goals below.');break;case 'resume':act(()=>{data.park=null},'Returned to your saved place. No task completion was changed.');break;case 'export':{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mission-control-backup-'+today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Backup exported. Store it privately.');break}}});
$('dashboard').addEventListener('change',e=>{const el=e.target;if(refreshClock()){message('A new day is loaded. Review the current plan before updating it.');return;}if(handleRefinedChange(el))return;if(el.dataset.check){act(()=>C.setStatus(data,el.dataset.week,el.dataset.check,el.checked?'complete':'incomplete',null,'',today));return}if(el.dataset.goal){act(()=>{const g=goalList(el.dataset.period,el.dataset.key).find(g=>g.id===el.dataset.goal);if(el.dataset.period==='week')C.setGoalStatus(data,el.dataset.key,g.id,el.checked?'complete':'incomplete',null,'',today);else g.done=el.checked});return}if(el.dataset.priority){act(()=>{data.priorities=el.checked?[...data.priorities,el.dataset.priority]:data.priorities.filter(a=>a!==el.dataset.priority)},'Priority areas updated. Recommendations have been refreshed.');return}if(el.id==='execute-day'){current=+el.value;render()}if(el.id==='history-week'){historyWeek=el.value;render()}if(el.id==='coach-target'){data.coach.area=el.value;data.coach.title=C.areas[el.value];data.coach.step=0;save();render()}});
$('dashboard').addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(refreshClock()){message('The date changed. Review today’s plan and submit again.');return}const v=Object.fromEntries(new FormData(f));if(handleTaskCoachSubmit(f,v)||handleRefinedSubmit(f,v))return;switch(f.dataset.form){case 'activity':act(()=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||v.date>today||isNaN(new Date(v.date+'T12:00:00').valueOf()))throw Error('Choose a valid activity date today or earlier.');C.logActivity(data,C.weekKey(v.date),v.text,v.area,v.date)},'Alternative saved. Broad goal credit updated; planned tasks and mobility are unchanged.');break;case 'status':act(()=>C.setStatus(data,f.dataset.week,f.dataset.id,v.status,v.due,v.reason,today));break;case 'replace':act(()=>{if(AcademicTracker.workload(data,today).allSubmitted)C.ensure(data,week).schoolDone=true;C.replaceSchool(data,week,+v.day,v.area)},'Replacement approved. Original block skipped; new block is incomplete.');break;case 'goal-add':act(()=>{if(f.dataset.period==='week'){const g=monthData().goals.find(g=>g.id===v.monthly&&!g.done);if(!g)throw Error('Choose an unfinished monthly goal.');if(!v.due||v.due<today)throw Error('Choose a valid due date.');v.monthlyMonth=month();v.parent=g.parent;v.area=g.area;v.metric='action'}else v.metric='milestones';C.adoptGoal(data,f.dataset.period,f.dataset.period==='month'?month():week,v)});break;case 'goal-edit':act(()=>{const g=goalList(f.dataset.period,f.dataset.key).find(g=>g.id===f.dataset.id);if(!v.title.trim())throw Error('Add a goal title.');if(f.dataset.period!=='long'&&(!Number.isFinite(+v.target)||+v.target<1||+v.target>999))throw Error('Use a target from 1 to 999.');if(f.dataset.period==='week'&&v.monthly){const linked=monthData().goals.find(m=>m.id===v.monthly);if(linked){v.monthlyMonth=month();v.parent=linked.parent;v.area=linked.area}}Object.assign(g,v,{target:+v.target||g.target})});break}});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(next?.version===4){data=C.upgrade(next);AcademicTracker.ensure(data);GoalPlanner.ensure(data);C.ensure(data,week);render();message('Updated from another tab on this device.')}}catch{}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshClock()});setInterval(refreshClock,1000);setInterval(tickFocusTimer,1000);
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();

/* Academic metadata is public; status, notes and verification edits stay in browser storage. */
function academicTask(t){if(t.area!=='education')return t;const x=AcademicTracker.workload(data,t.due||t.date).next;return x?{...t,assignment:x}:t}
function academicDeadline(x){return AcademicTracker.deadlineLabel(x,data.timezone)}
function academicBlock(t){const w=AcademicTracker.workload(data,t.due||t.date),x=w.next;return `<div class="academic-inline">${x?`<strong>Study focus: ${esc(x.title)}</strong><span>${esc(academicDeadline(x))} · ${esc(x.status)}</span>${x.kind==='Discussion'?'<span>Plan a second visit for classmates’ responses.</span>':''}`:w.allSubmitted?'<strong>Required work is reported submitted. Consider a monthly priority instead.</strong>':'<span>No verified study focus yet. Review the tracker.</span>'}<button class="button" data-view="academics">Academic Tracker</button></div>`}
function academicStudyNote(){const r=AcademicTracker.recommendation(data,today,Date.now(),C),goals=monthData().goals.filter(g=>!g.done);return `<div class="status-note"><strong>Academic study plan · ${r.week>=1&&r.week<=8?'Course week '+r.week:'Outside the course term'}</strong><p>${r.next?`Prioritize ${esc(r.next.title)}. ${r.rows.some(x=>x.kind==='Discussion')?'Allow a separate return visit for classmate responses; quizzes are tracked separately.':''}`:r.allSubmitted?'This week’s required work is reported submitted. You may approve a replacement for an unused study block.':'Review academic deadlines and outstanding work.'}</p>${r.urgent?`<p class="deadline-alert">${esc(r.urgent.title)} is due before your next available study block${r.study?' ('+esc(dateLabel(r.study.date))+' · '+esc(r.study.time)+')':''}. Set aside an earlier work session${AcademicTracker.deadline(r.urgent)<Date.now()?'; its recorded deadline has already passed, verify late options in UMGC':''}.</p>`:''}${r.next?.kind==='Discussion'?'<p>Draft your initial response first, then return for required replies. Verify both deadlines in UMGC.</p>':''}${r.allSubmitted?`<p>Possible replacement: ${esc(goals[0]?.title||'business development, Skool learning, Forex education or photography')}. Use Today’s “Coursework finished ahead of schedule?” control to approve a replacement.</p>`:''}<button class="button" data-view="academics">Review academic workload</button></div>`}
function academicCard(x,compact=false){const count=x.checked.filter(i=>i>=0&&i<x.steps.length).length,at=AcademicTracker.deadline(x),late=x.status!=='Submitted'&&at!==null&&at<Date.now();return `<article class="academic-card" data-assignment="${esc(x.id)}"><div class="academic-card-head"><div><span class="eyebrow">WEEK ${x.week} · ${esc(x.kind)}</span><h3>${esc(x.title)}</h3></div><button class="button" data-academic-coach="${esc(x.id)}" aria-label="Coach Me: ${esc(x.title)}">Coach Me</button></div><p class="muted">${esc(x.course)}</p><p class="academic-deadline ${late?'deadline-alert':''}"><strong>${late?'Deadline passed · ':''}${esc(academicDeadline(x))}</strong></p><span class="badge">${esc(x.unreviewed?'Status not recorded':x.status)}</span>${x.reported?`<span class="muted"> Initially reported: ${esc(x.reported)}</span>`:''}${x.id==='written-4'?'<p class="status-note">Source conflict: the syllabus case description differs from the active assignment folder. This title follows the reported active listing. Verify its requirements in UMGC.</p>':''}${x.id==='quiz-1'?'<p class="muted">Attempts used do not establish a grade. Score and Week 1 participation remain unverified; no completion is inferred.</p>':''}${x.kind==='Discussion'?'<p class="muted">Plan an initial post and a later visit for required classmate responses. Their individual deadlines need verification.</p>':''}<div class="actions"><a class="button" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${x.url===AcademicTracker.course.url?'Open UMGC course':'Open verified UMGC page'} ↗</a></div><details class="academic-details"><summary>More Details · ${count}/${x.steps.length} preparation steps</summary><p class="muted">Deadline source: ${esc(x.deadlineSource)}. Written times use America/New_York, converted to ${esc(data.timezone)}. Confirm the LMS display before relying on them.</p><p>Use the active folder and rubric as the authority. These are suggested preparation steps, not imported course materials.</p>${x.steps.map((line,i)=>`<label class="academic-step"><input type="checkbox" data-academic-step="${i}" data-academic-id="${esc(x.id)}" ${x.checked.includes(i)?'checked':''}>${esc(line)}</label>`).join('')}<p class="muted">All steps checked does not mean submitted. Only your explicit Submitted status records submission.</p>${x.notes?`<p><strong>My notes:</strong> ${esc(x.notes)}</p>`:''}${compact?`<button class="button" data-view="academics">Manage assignment</button>`:''}</details>${!compact?`<details><summary>Update status, notes or verified deadline</summary>${academicEdit(x)}</details>`:''}</article>`}
function academicEdit(x){return `<form data-form="academic-edit" data-id="${esc(x.id)}"><label>Assignment status<select name="status">${AcademicTracker.statuses.map(s=>option(s,s,x.status)).join('')}</select></label><p class="muted">Choose Submitted only after you verify submission in UMGC. Ready to Submit is still outstanding.</p><label>Optional personal notes<textarea name="notes" maxlength="2000">${esc(x.notes)}</textarea></label><label>Relevant UMGC page<input type="url" name="url" required value="${esc(x.url)}"></label><p class="muted">Course home is the fallback until you paste a verified assignment, discussion or quiz link. No folder URL is guessed.</p><label>Verified due date in Eastern Time, optional<input name="dueDate" type="date" value="${esc(x.dueDate||'')}"></label><label>Verified time in Eastern Time, optional<input name="dueTime" type="time" value="${esc(x.dueTime||'')}"></label><label class="academic-step"><input type="checkbox" name="deadlineVerified" ${x.deadlineVerified?'checked':''}>I checked this deadline against UMGC, including its displayed timezone</label><label>Optional personal requirements or steps, one per line<textarea name="steps" maxlength="4000">${esc(x.steps.join('\n'))}</textarea></label><button class="primary">Save academic record</button></form>`}
function renderAcademics(){const all=AcademicTracker.items(data),submitted=all.filter(x=>x.status==='Submitted');return `<h2>Academic Assignment Tracker</h2><p class="section-intro">${esc(AcademicTracker.course.title)}<br>October 14 – December 8, 2026. Your schedule sets when you study; this tracker sets what you work on.</p><p class="muted">Manually maintained on this device. No UMGC synchronization. Initial metadata comes from your reported schedule; check the active LMS for changes.</p>${meter(submitted.length,all.length,'Manually confirmed submissions')}${academicStudyNote()}<details class="panel"><summary>Source verification & timezone</summary><p>Written deadlines use the syllabus’s Tuesday 11:59 PM Eastern rule, equivalent to 8:59 PM Pacific. Daylight saving changes are applied by date. Assessment dates are provisional week-ending Tuesdays, with no invented due time.</p><p class="deadline-alert">Live LMS timezone has not been verified. If its displayed deadline differs, verify the course timezone and active folder, then update the record. Week 4 follows the active listing reported by you, with its syllabus conflict flagged.</p><form data-form="academic-source"><label>Observed LMS timezone, optional<input name="lmsTimezone" maxlength="120" value="${esc(data.academics.lmsTimezone)}" placeholder="e.g. Eastern, as shown in my account"></label><label>Verification notes, optional<textarea name="verificationNote" maxlength="1200">${esc(data.academics.verificationNote)}</textarea></label><button class="button">Save source notes</button></form></details><h3>Outstanding work</h3>${all.filter(x=>x.status!=='Submitted').sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).map(x=>academicCard(x)).join('')||'<p>All tracked items are reported submitted.</p>'}<details class="panel" ${submitted.length?'open':''}><summary>Submitted assignments · ${submitted.length}</summary>${submitted.map(x=>academicCard(x)).join('')||'<p class="muted">No submissions recorded. Checklists and study-block completion never change this count.</p>'}</details><p class="muted">Grades and participation are not inferred. Store only your own brief notes, not passwords, student IDs or private course documents.</p>`}
function academicQueue(){const items=AcademicTracker.pending(data,today);return `<section aria-label="Academic actions"><h3>Academic actions · approaching deadlines</h3><p class="muted">Assignments persist until explicitly reported submitted. Study time and submission are separate records.</p>${items.slice(0,3).map(x=>academicCard(x,true)).join('')||'<p class="empty">No unsubmitted current-week academic actions recorded. Check the tracker for future or unverified items.</p>'}<button class="button" data-view="academics">All academic assignments</button></section>`}
function academicProgress(){const all=AcademicTracker.items(data),done=all.filter(x=>x.status==='Submitted'),pending=all.filter(x=>x.status!=='Submitted'&&x.dueDate).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));return `<section aria-label="Academic progress"><h3>Academic submissions & deadlines</h3>${meter(done.length,all.length,'Manually confirmed submissions')}<p class="muted">Submission records are separate from completed study blocks and preparation steps. Grades are not inferred.</p>${done.map(x=>`<p>✓ ${esc(x.title)} · Submitted, manually recorded</p>`).join('')}${pending.slice(0,3).map(x=>`<p><strong>${esc(x.title)}</strong><br>${esc(academicDeadline(x))} · ${esc(x.status)}</p>`).join('')}<button class="button" data-view="academics">Open Academic Tracker</button></section>`}
function handleAcademicClick(b){if(!b.dataset.academicCoach)return false;const x=AcademicTracker.items(data).find(x=>x.id===b.dataset.academicCoach);if(!x)return true;data.taskCoach={active:true,task:{kind:'academic',id:x.id,title:x.title,time:academicDeadline(x),date:today,area:'education',assignment:x,ref:'academic|'+AcademicTracker.course.id+'|'+x.id},mode:null,stage:'modes',step:0,from:null,target:'',wait:'',note:''};save();switchView('coach');window.scrollTo(0,0);return true}
function handleAcademicSubmit(f,v){if(f.dataset.form==='academic-source'){act(()=>{data.academics.lmsTimezone=v.lmsTimezone.trim();data.academics.verificationNote=v.verificationNote.trim()},'Source verification notes saved locally. No LMS connection was made.');return true}if(f.dataset.form!=='academic-edit')return false;act(()=>{const previous=AcademicTracker.items(data).find(x=>x.id===f.dataset.id),steps=v.steps.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,30),changed=steps.join('\n')!==previous.steps.join('\n'),verified=v.deadlineVerified==='on';if(!steps.length)throw Error('Keep at least one preparation step.');if(v.dueTime&&!v.dueDate)throw Error('A deadline time needs a date.');if((v.dueDate!==(previous.dueDate||'')||v.dueTime!==(previous.dueTime||''))&&!verified)throw Error('Confirm you verified the changed deadline in UMGC.');AcademicTracker.update(data,f.dataset.id,{status:v.status,notes:v.notes.trim(),url:v.url.trim(),dueDate:v.dueDate||null,dueTime:v.dueTime||null,deadlineVerified:verified,deadlineSource:verified?'Manually verified in UMGC':previous.deadlineSource,steps,checked:changed?[]:previous.checked,unreviewed:false,updatedAt:new Date().toISOString()})},'Academic record saved locally. No submission was sent to UMGC.');return true}

$('dashboard').addEventListener('input',e=>{persistWeeklyInput(e.target)});
